'use strict';
const assert=require('node:assert/strict');
const {inspectPowerglassWinningKo}=
  require('./agent37-powerglass-winning-ko-native.cjs');
const {withPaperKoBeforeEndTurn,VERSION}=
  require('./agent37-paper-ko-before-endturn-hook.cjs');

/**
 * Genuine pinned-Store A/B outcomes. Source-invariant actor hands and printed
 * cards are generated by the same isolated code path; only EndTurn ordering
 * changes. Each arm settles all native prompts with real card object answers.
 * @returns {object} Side-by-side terminal, KO, Prize and Energy receipts.
 */
function auditFullSettlement(){
  const scenarios=[
    {label:'regularPrize',lastPrize:false,opponentHasBench:true},
    {label:'lastPrize',lastPrize:true,opponentHasBench:true},
    {label:'lastPokemon',lastPrize:false,opponentHasBench:false}
  ];
  const arms=scenarios.map(({label,...options})=>{
    const args={...options,settleAll:true};
    const baseline=inspectPowerglassWinningKo(args);
    const treatment=withPaperKoBeforeEndTurn(
      ()=>inspectPowerglassWinningKo(args));
    const b=baseline.finalState,t=treatment.result.finalState;
    assert.equal(treatment.audit.originalStoreMethodRestored,true);
    assert.equal(treatment.audit.attackEndTurnIntercepts,1);
    assert.equal(b.openPrompts.length,0);
    assert.equal(t.openPrompts.length,0);
    if(label==='regularPrize'){
      assert.equal(b.ownerPrizesRemaining,5);
      assert.equal(t.ownerPrizesRemaining,5);
      assert.equal(b.sourceActive,'Tapu Lele-GX GRI');
      assert.equal(t.sourceActive,'Tapu Lele-GX GRI');
      assert.deepEqual(treatment.result.seenPrompts.filter(x=>x!=='WaitPrompt'),
        ['ChoosePrizePrompt','ChoosePokemonPrompt','AttachEnergyPrompt']);
      assert.deepEqual(baseline.seenPrompts.filter(x=>x!=='WaitPrompt'),
        ['AttachEnergyPrompt','ChoosePrizePrompt','ChoosePokemonPrompt']);
      assert.equal(treatment.audit.completedAttackEndTurns,1);
    }else if(label==='lastPrize'){
      assert.equal(b.ownerPrizesRemaining,0);
      assert.equal(t.ownerPrizesRemaining,0);
      assert.equal(b.finished,true);
      assert.equal(t.finished,true);
      assert.equal(treatment.audit.terminalEndTurnsSuppressed,1);
      assert.deepEqual(treatment.result.seenPrompts.filter(x=>x!=='WaitPrompt'),
        []);
    }else{
      assert.equal(t.finished,true);
      assert.equal(treatment.audit.terminalEndTurnsSuppressed,1);
      assert.equal(treatment.result.seenPrompts.includes('AttachEnergyPrompt'),
        false);
      assert.equal(treatment.result.opponentRemainingBench,0);
    }
    return {label,baseline:{
      firstChoice:baseline.firstChoicePrompt,sequence:baseline.seenPrompts,
      final:b
    },paperOrder:{
      firstChoice:treatment.result.firstChoicePrompt,
      sequence:treatment.result.seenPrompts,final:t,
      audit:treatment.audit
    }};
  });
  return {
    version:VERSION,realPinnedStore:true,
    bothWinningConditionsTested:true,
    completedPrizeAndEndTurnPhysicalPromptChains:true,
    qualifiedCompetitiveGames:0,arms
  };
}
if(require.main===module)
  process.stdout.write(JSON.stringify(auditFullSettlement(),null,2)+'\n');
module.exports={auditFullSettlement};
